        return []

    result = []
    min_val = float('inf')
    max_val = float('-inf')

    for num in lst:
        if num < min_val:
            min_val = num
        elif num > max_val:
            max_val = num

    result.append(min_val)
    lst.remove(min_val)

    while lst:
        max_val = float('-inf')
        for num in lst:
            if num > max_val:
                max_val = num
        result.append(max_val)
        lst.remove(max_val)

    return result

