def total_match(lst1, lst2):
    total_chars_list1 = sum(len(s) for s in lst1)
    total_chars_list2 = sum(len(s) for s in lst2)

    if total_chars_list1 < total_chars_list2:
        return lst1
    elif total_chars_list2 < total_chars_list1:
        return lst2
    else:
        return lst1

