def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        if x in row:
            coordinates = [(j, len(row) - 1 - k) for k, j in enumerate(range(len(row))) if row[j] == x]
            result.extend([(i, j) for j in sorted(coordinates, key=lambda t: t[1], reverse=True)])
    return sorted(result, key=lambda t: t[0])

def next_smallest(lst):
    if len(lst) < 2:
        return None
    lst.sort()
    smallest = lst[0]
    second_smallest = None
    for num in lst:
        if num > smallest:
            second_smallest = smallest
            smallest = num
        elif num < smallest and num != smallest:
            second_smallest = num
    return second_smallest if second_smallest is not None else None

