def choose_num(x, y):
    # Ensure x is less than or equal to y
    if x > y:
        return -1

    # Find the biggest even number in the range [x, y]
    even_num = y
    while even_num > x and even_num % 2 != 0:
        even_num -= 1

    # Return -1 if no even number is found
    if even_num % 2 != 0:
        return -1
    else:
        return even_num

