    vowels = 'AEIOU'
    vowels_lower = 'aeiou'

    for i in range(len(word) - 2, -1, -1):
        if word[i] in vowels:
            if word[i-1] not in vowels and word[i+1] not in vowels:
                if word[i] in vowels_lower:
                    return word[i]
                else:
                    return word[i]
        elif word[i-1] in vowels and word[i+1] not in vowels:
            if word[i] in vowels_lower:
                return word[i]
            else:
                return word[i]

    return ""

