def match_parens(lst):
    str1, str2 = lst
    stack = []

    for c in str1 + str2:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if stack:
                stack.pop()
            else:
                stack.append(c)

    return 'Yes' if not stack else 'No'

print(match_parens(['()(', ')']))  # 'Yes'
print(match_parens([')', ')']))  # 'No'

