def file_name_check(file_name):
    # Check if the file's name contains exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file's name into two substrings: before and after the dot
    before_dot, after_dot = file_name.split('.')

    # Check if the substring before the dot is not empty and starts with a latin alphapet letter
    if not before_dot or not before_dot[0].isalpha():
        return 'No'

    # Check if the substring after the dot is one of the valid extensions
    if after_dot not in ['txt', 'exe', 'dll']:
        return 'No'

    # Check if there are more than three digits in the file's name
    if sum(c.isdigit() for c in file_name) > 3:
        return 'No'

    return 'Yes'

